code.cpp:
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long x;
    long long y;
    cin >> x >> y;

    if (x == 0 && y == 0) {
        cout << "origin" << endl;
    } else if (y == 0) {
        cout << "x-axis" << endl;
    } else if (x == 0) {
        cout << "y-axis" << endl;
    } else if (x > 0 && y > 0) {
        cout << "quadrant 1" << endl;
    } else if (x < 0 && y > 0) {
        cout << "quadrant 2" << endl;
    } else if (x < 0 && y < 0) {
        cout << "quadrant 3" << endl;
    } else {
        cout << "quadrant 4" << endl;
    }

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();

        if (x == 0 && y == 0) {
            System.out.println("origin");
        } else if (y == 0) {
            System.out.println("x-axis");
        } else if (x == 0) {
            System.out.println("y-axis");
        } else if (x > 0 && y > 0) {
            System.out.println("quadrant 1");
        } else if (x < 0 && y > 0) {
            System.out.println("quadrant 2");
        } else if (x < 0 && y < 0) {
            System.out.println("quadrant 3");
        } else {
            System.out.println("quadrant 4");
        }
    }
}
